def find_marker2(g):
 bg=Counter(v for row in g for v in row).most_common(1)[0][0]; cand=[]
 for col,pts in comps_grid(g):
  if col==bg: continue
  rs=[r for r,c in pts]; cs=[c for r,c in pts]; t,b,l,rr=min(rs),max(rs),min(cs),max(cs); hh=b-t+1; ww=rr-l+1; ss=set(pts)
  if min(hh,ww)<3:continue
  edges={'top':sum((t,c) in ss for c in range(l,rr+1)), 'bottom':sum((b,c) in ss for c in range(l,rr+1)), 'left':sum((r,l) in ss for r in range(t,b+1)), 'right':sum((r,rr) in ss for r in range(t,b+1))}
  for e1,e2,er,ec in [('top','left',t,l),('top','right',t,rr),('bottom','left',b,l),('bottom','right',b,rr)]:
   len1=ww if e1 in ('top','bottom') else hh; len2=hh if e2 in ('left','right') else ww
   if edges[e1]==len1 and edges[e2]==len2 and len(pts)==len1+len2-1:
    cand.append((len(pts),col,pts,(t,b,l,rr),(er,ec),e1,e2))
 if not cand:return None
 return max(cand,key=lambda x:x[0])
def transform_new2(g):
 out=[row[:] for row in g]; bg=Counter(v for row in g for v in row).most_common(1)[0][0]; mk=find_marker2(g)
 if not mk:return out,None
 n,col,mp,bbox,elbow,e1,e2=mk; t,b,l,rr=bbox; er,ec=elbow
 direction=-1 if ec==l else 1
 targets=[]
 for co,pts in comps_grid(g):
  if co in (bg,col): continue
  if direction<0 and max(c for r,c in pts)>=ec: continue
  if direction>0 and min(c for r,c in pts)<=ec: continue
  dist=min(abs(r-y)+abs(c-x) for r,c in pts for y,x in mp)
  targets.append((dist,co,pts))
 if not targets:return out,(mk,None)
 d,co,pts=min(targets,key=lambda x:x[0])
 for r,c in pts:out[r][c]=col
 return out,(mk,(d,co,pts))
